UPDATE lessons SET title='Editing and Publishing an Information Report',data=json_patch(data,'{"seed_key":"s2-eng-y3-w10-l2","title":"Editing and Publishing an Information Report","stage":"Stage 2","learning_area":"English","year_level":3,"week":10,"lesson_number":2,"duration_minutes":60,"child_mission":"Investigate editing and publishing an information report with worked teaching and a new independent challenge.","learning_intention":"We are learning to understand and apply editing and publishing an information report clearly.","success_criteria":["Explain the key idea.","Use a worked model.","Complete guided practice.","Solve an independent task.","Explain one check or correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept review","cards":[{"front":"Check factual claims","back":"''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''."},{"front":"Organise paragraphs and headings","back":"Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion."},{"front":"Edit sentence boundaries and grammar","back":"Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops."},{"front":"Publish with a helpful visual","back":"Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram."}]}],"printable_resource":{"title":"Editing and Publishing an Information Report","instructions":"Read, model, practise, then independently respond.","passage":"''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''.","prompts":["Explain the topic.","Show one model.","Try a task.","Check the answer."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Check factual claims","explain":"''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''. The important concept here is: check factual claims.","example":"**Worked example:** ''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''.\n\n**Your practice:** Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''.","check":{"question":"Which claim needs checking?","options":["Every plant grows identically","Some plants have roots","The draft describes plants","A sunflower was observed"],"correct_index":0,"explanation":"Every plant grows identically is correct. ''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''."},"visual_before":[{"episode":{"title":"Editing and Publishing an Information Report","transcript":"pip: I need to learn editing and publishing an information report. What should I check first?\njuno: Identify the relevant numbers or exact words, then follow a worked example.\npip: I''ll explain my strategy before deciding if the result is accurate.\njuno: Pause and try one step yourself, checking it against the evidence before moving on.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I need to learn editing and publishing an information report. What should I check first?"},{"who":"juno","text":"Identify the relevant numbers or exact words, then follow a worked example."},{"who":"pip","text":"I''ll explain my strategy before deciding if the result is accurate."},{"who":"juno","text":"Pause and try one step yourself, checking it against the evidence before moving on.","pause_after":true}]}]}}]},{"icon":"📚","title":"Organise paragraphs and headings","explain":"Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion. The important concept here is: organise paragraphs and headings.","example":"**Worked example:** Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion.\n\n**Your practice:** Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion.","check":{"question":"Correct plural verb?","options":["Native bees live","Native bees lives","Native bees living is","Native bees was live"],"correct_index":0,"explanation":"Native bees live is correct. Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion."}},{"icon":"✏️","title":"Edit sentence boundaries and grammar","explain":"Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops. The important concept here is: edit sentence boundaries and grammar.","example":"**Worked example:** Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops.\n\n**Your practice:** Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops.","check":{"question":"Correct spelling?","options":["pollen","polen","pollan","polllen"],"correct_index":0,"explanation":"pollen is correct. Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops."}},{"icon":"✅","title":"Publish with a helpful visual","explain":"Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram. The important concept here is: publish with a helpful visual.","example":"**Worked example:** Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram.\n\n**Your practice:** Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram.","check":{"question":"Which is substantive revision?","options":["Qualifying an unsupported universal claim","Fixing polen","Capitalising Native","Adding a full stop"],"correct_index":0,"explanation":"Qualifying an unsupported universal claim is correct. Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram."}}],"worked_example":"**Step 1: Check factual claims** ''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''.\n\n**Step 2: Organise paragraphs and headings** Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion.\n\n**Step 3: Edit sentence boundaries and grammar** Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops.\n\n**Step 4: Publish with a helpful visual** Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 170\"><rect width=\"570\" height=\"170\" rx=\"12\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"26\" font-family=\"Arial\" font-size=\"18\">Editing and Publishing an Information Report</text><rect x=\"8\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"15\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Check factual claim</text><rect x=\"148\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"155\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Organise paragraphs</text><rect x=\"288\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"295\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Edit sentence bound</text><rect x=\"428\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"435\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Publish with a help</text></svg>","alt":"Four concepts for Editing and Publishing an Information Report","caption":"Follow the explanations for each learning concept."}],"guided_practice":"Study the four models and practise their methods: ''All plants need bees'' is unsupported; change to ''Some plants benefit from pollen transfer by bees''. Group the report under ''Visiting Flowers'' and ''Moving Pollen'', with a clear introduction and conclusion. Correct ''native bees lives'' to ''Native bees live''; change ''polen'' to ''pollen'' and add full stops. Publish under the title ''Native Bees and Flowers'' with a caption explaining a labelled flower diagram. Then explain how the facts or calculation check the result.","independent_task":"Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.","response_prompt":"Revise this draft into a 120–160-word report with two headings, a short conclusion and a labelled diagram caption: ''plants use sunlight to grow some plants needs water. Our sunflower was biggest. Every plant grows in the same way! plants have roots and leaves.'' Show three edits and two meaningful revisions.","quiz":[{"type":"multiple_choice","question":"Which claim needs checking?","options":["Every plant grows identically","Some plants have roots","The draft describes plants","A sunflower was observed"],"correct_index":0,"explanation":"Every plant grows identically is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Correct plural verb?","options":["Native bees live","Native bees lives","Native bees living is","Native bees was live"],"correct_index":0,"explanation":"Native bees live is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Correct spelling?","options":["pollen","polen","pollan","polllen"],"correct_index":0,"explanation":"pollen is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which is substantive revision?","options":["Qualifying an unsupported universal claim","Fixing polen","Capitalising Native","Adding a full stop"],"correct_index":0,"explanation":"Qualifying an unsupported universal claim is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which heading suits bee behaviour?","options":["Visiting Flowers","Car Racing","Sport Results","A Birthday"],"correct_index":0,"explanation":"Visiting Flowers is correct; compare with the teaching example."},{"type":"multiple_choice","question":"What should a caption explain?","options":["The content of a visual","The author''s favourite colour","An unrelated fact","The page number only"],"correct_index":0,"explanation":"The content of a visual is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which is careful phrasing?","options":["Some plants benefit from pollination","All plants need bees","All bees behave alike","Pollen never moves"],"correct_index":0,"explanation":"Some plants benefit from pollination is correct; compare with the teaching example."},{"type":"multiple_choice","question":"What should be checked before publishing?","options":["Facts, language, layout and attribution","Only decorations","Only word count","Only font style"],"correct_index":0,"explanation":"Facts, language, layout and attribution is correct; compare with the teaching example."},{"type":"short_answer","question":"Complete the independent challenge and show the method.","sample_answer":"A suitable report describes that many plants use sunlight in photosynthesis, roots may absorb water, and the class observed a tall sunflower. The two headings can be ''How Plants Grow'' and ''Our Garden Observation''. Caption: ''Roots, stem and leaves of a flowering plant''.","marking_guide":"Check the full task against correct information and working.","explanation":"Specific evidence is essential."},{"type":"short_answer","question":"Explain a mistake, correction or important limitation.","sample_answer":"Edits include capitals, sentence boundaries and ''plants need''. Revisions qualify the unsupported ''Every plant grows in the same way'' and describe the sunflower only as a local observation.","marking_guide":"Require a correct reason and topic-specific example.","explanation":"Use evidence to explain the change."}],"parent_notes":"Parent: Check the independent attempt before showing models.\n\nWritten model 1: A suitable report describes that many plants use sunlight in photosynthesis, roots may absorb water, and the class observed a tall sunflower. The two headings can be ''How Plants Grow'' and ''Our Garden Observation''. Caption: ''Roots, stem and leaves of a flowering plant''.\n\nWritten model 2: Edits include capitals, sentence boundaries and ''plants need''. Revisions qualify the unsupported ''Every plant grows in the same way'' and describe the sunflower only as a local observation.\n\nRetain the student''s own evidence; NESA alignment is still unverified.","evidence_instructions":"Keep guided work, independent answers and written assessments.","offline_alternative":"Complete the tasks on paper and keep written or photographed evidence.","extension":"Design a new editing and publishing an information report task and explain the answer.","stage_hints":{"accept":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach0":["Review Check factual claims.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach1":["Review Organise paragraphs and headings.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach2":["Review Edit sentence boundaries and grammar.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach3":["Review Publish with a helpful visual.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"learn":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"guided":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"write":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"quiz":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"submit":["Review Editing and Publishing an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."]}}') WHERE seed_key='s2-eng-y3-w10-l2';
UPDATE lessons SET title='Commas and Apostrophes: Punctuation Review',data=json_patch(data,'{"seed_key":"s2-eng-y3-w10-l3","title":"Commas and Apostrophes: Punctuation Review","stage":"Stage 2","learning_area":"English","year_level":3,"week":10,"lesson_number":3,"duration_minutes":60,"child_mission":"Investigate commas and apostrophes: punctuation review with worked teaching and a new independent challenge.","learning_intention":"We are learning to understand and apply commas and apostrophes: punctuation review clearly.","success_criteria":["Explain the key idea.","Use a worked model.","Complete guided practice.","Solve an independent task.","Explain one check or correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept review","cards":[{"front":"Separate items in lists","back":"Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided."},{"front":"Punctuate introductory clauses","back":"Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma."},{"front":"Mark missing letters in contractions","back":"Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''."},{"front":"Distinguish possession and plurals","back":"''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural."}]}],"printable_resource":{"title":"Commas and Apostrophes: Punctuation Review","instructions":"Read, model, practise, then independently respond.","passage":"Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided.","prompts":["Explain the topic.","Show one model.","Try a task.","Check the answer."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Separate items in lists","explain":"Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided. The important concept here is: separate items in lists.","example":"**Worked example:** Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided.\n\n**Your practice:** Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided.","check":{"question":"Which list is punctuated correctly?","options":["Pencils, books and rulers","Pencils books, and rulers","Pencils books and, rulers","Pencils, books, and, rulers"],"correct_index":0,"explanation":"Pencils, books and rulers is correct. Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided."},"visual_before":[{"episode":{"title":"Commas and Apostrophes: Punctuation Review","transcript":"pip: I need to learn commas and apostrophes: punctuation review. What should I check first?\njuno: Identify the relevant numbers or exact words, then follow a worked example.\npip: I''ll explain my strategy before deciding if the result is accurate.\njuno: Pause and try one step yourself, checking it against the evidence before moving on.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I need to learn commas and apostrophes: punctuation review. What should I check first?"},{"who":"juno","text":"Identify the relevant numbers or exact words, then follow a worked example."},{"who":"pip","text":"I''ll explain my strategy before deciding if the result is accurate."},{"who":"juno","text":"Pause and try one step yourself, checking it against the evidence before moving on.","pause_after":true}]}]}}]},{"icon":"📚","title":"Punctuate introductory clauses","explain":"Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma. The important concept here is: punctuate introductory clauses.","example":"**Worked example:** Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma.\n\n**Your practice:** Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma.","check":{"question":"Which opening is correctly punctuated?","options":["After lunch, we read.","After, lunch we read.","After lunch we, read.","After lunch we read,"],"correct_index":0,"explanation":"After lunch, we read. is correct. Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma."}},{"icon":"✏️","title":"Mark missing letters in contractions","explain":"Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''. The important concept here is: mark missing letters in contractions.","example":"**Worked example:** Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''.\n\n**Your practice:** Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''.","check":{"question":"Correct contraction?","options":["didn''t","didnt","dids''nt","did''nt"],"correct_index":0,"explanation":"didn''t is correct. Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''."}},{"icon":"✅","title":"Distinguish possession and plurals","explain":"''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural. The important concept here is: distinguish possession and plurals.","example":"**Worked example:** ''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural.\n\n**Your practice:** Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural.","check":{"question":"One bee owning wings?","options":["The bee''s wings","The bees wings","The bees'' wings","The bee wings''"],"correct_index":0,"explanation":"The bee''s wings is correct. ''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural."}}],"worked_example":"**Step 1: Separate items in lists** Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided.\n\n**Step 2: Punctuate introductory clauses** Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma.\n\n**Step 3: Mark missing letters in contractions** Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''.\n\n**Step 4: Distinguish possession and plurals** ''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 170\"><rect width=\"570\" height=\"170\" rx=\"12\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"26\" font-family=\"Arial\" font-size=\"18\">Commas and Apostrophes: Punctuation Review</text><rect x=\"8\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"15\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Separate items in l</text><rect x=\"148\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"155\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Punctuate introduct</text><rect x=\"288\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"295\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Mark missing letter</text><rect x=\"428\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"435\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Distinguish possess</text></svg>","alt":"Four concepts for Commas and Apostrophes: Punctuation Review","caption":"Follow the explanations for each learning concept."}],"guided_practice":"Study the four models and practise their methods: Write ''bees, butterflies and ants'' rather than leaving the listed nouns undivided. Write ''After the rain stopped, the children returned.'' The opening dependent clause is followed by a comma. Use ''didn''t'' for ''did not'' and ''can''t'' for ''cannot''. ''The bee''s wing'' belongs to one bee; ''the bees'' wings'' belongs to multiple bees; ''bees'' alone is a plural. Then explain how the facts or calculation check the result.","independent_task":"Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.","response_prompt":"Correct and explain: ''before school we packed pencils notebooks and rulers. the dogs lead was by its bowl. the two dogs collars were blue. we cant enter. although it rained we walked.'' Then write a sentence showing its versus it''s.","quiz":[{"type":"multiple_choice","question":"Which list is punctuated correctly?","options":["Pencils, books and rulers","Pencils books, and rulers","Pencils books and, rulers","Pencils, books, and, rulers"],"correct_index":0,"explanation":"Pencils, books and rulers is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which opening is correctly punctuated?","options":["After lunch, we read.","After, lunch we read.","After lunch we, read.","After lunch we read,"],"correct_index":0,"explanation":"After lunch, we read. is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Correct contraction?","options":["didn''t","didnt","dids''nt","did''nt"],"correct_index":0,"explanation":"didn''t is correct; compare with the teaching example."},{"type":"multiple_choice","question":"One bee owning wings?","options":["The bee''s wings","The bees wings","The bees'' wings","The bee wings''"],"correct_index":0,"explanation":"The bee''s wings is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Multiple dogs owning collars?","options":["The dogs'' collars","The dog''s collars","The dogs collars''","The dogs''s collars"],"correct_index":0,"explanation":"The dogs'' collars is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which is a plain plural?","options":["Three bees","Three bee''s","Three be''es","Three bee''s''"],"correct_index":0,"explanation":"Three bees is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Correct possessive its?","options":["The dog wagged its tail.","The dog wagged it''s tail.","Its raining.","Its'' tail moved."],"correct_index":0,"explanation":"The dog wagged its tail. is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which means ''it is''?","options":["it''s","its","its''","itss"],"correct_index":0,"explanation":"it''s is correct; compare with the teaching example."},{"type":"short_answer","question":"Complete the independent challenge and show the method.","sample_answer":"Before school, we packed pencils, notebooks and rulers. The dog''s lead was by its bowl. The two dogs'' collars were blue. We can''t enter. Although it rained, we walked.","marking_guide":"Check the full task against correct information and working.","explanation":"Specific evidence is essential."},{"type":"short_answer","question":"Explain a mistake, correction or important limitation.","sample_answer":"''It''s'' means ''it is'', as in ''It''s raining''. ''Its'' is possessive, as in ''The dog wagged its tail''. A contraction uses apostrophe for a missing letter; possession identifies ownership.","marking_guide":"Require a correct reason and topic-specific example.","explanation":"Use evidence to explain the change."}],"parent_notes":"Parent: Check the independent attempt before showing models.\n\nWritten model 1: Before school, we packed pencils, notebooks and rulers. The dog''s lead was by its bowl. The two dogs'' collars were blue. We can''t enter. Although it rained, we walked.\n\nWritten model 2: ''It''s'' means ''it is'', as in ''It''s raining''. ''Its'' is possessive, as in ''The dog wagged its tail''. A contraction uses apostrophe for a missing letter; possession identifies ownership.\n\nRetain the student''s own evidence; NESA alignment is still unverified.","evidence_instructions":"Keep guided work, independent answers and written assessments.","offline_alternative":"Complete the tasks on paper and keep written or photographed evidence.","extension":"Design a new commas and apostrophes: punctuation review task and explain the answer.","stage_hints":{"accept":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach0":["Review Separate items in lists.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach1":["Review Punctuate introductory clauses.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach2":["Review Mark missing letters in contractions.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach3":["Review Distinguish possession and plurals.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"learn":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"guided":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"write":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"quiz":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"submit":["Review Commas and Apostrophes: Punctuation Review.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."]}}') WHERE seed_key='s2-eng-y3-w10-l3';
UPDATE lessons SET title='Presenting an Information Report',data=json_patch(data,'{"seed_key":"s2-eng-y3-w10-l4","title":"Presenting an Information Report","stage":"Stage 2","learning_area":"English","year_level":3,"week":10,"lesson_number":4,"duration_minutes":60,"child_mission":"Investigate presenting an information report with worked teaching and a new independent challenge.","learning_intention":"We are learning to understand and apply presenting an information report clearly.","success_criteria":["Explain the key idea.","Use a worked model.","Complete guided practice.","Solve an independent task.","Explain one check or correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept review","cards":[{"front":"Introduce topic and purpose","back":"Open: ''Today I''ll share what our class''s garden insect survey found.''"},{"front":"Explain a labelled visual","back":"Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations."},{"front":"Speak clearly using concise notes","back":"Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences."},{"front":"Respond to a question using evidence","back":"If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results."}]}],"printable_resource":{"title":"Presenting an Information Report","instructions":"Read, model, practise, then independently respond.","passage":"Open: ''Today I''ll share what our class''s garden insect survey found.''","prompts":["Explain the topic.","Show one model.","Try a task.","Check the answer."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Introduce topic and purpose","explain":"Open: ''Today I''ll share what our class''s garden insect survey found.'' The important concept here is: introduce topic and purpose.","example":"**Worked example:** Open: ''Today I''ll share what our class''s garden insect survey found.''\n\n**Your practice:** Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Open: ''Today I''ll share what our class''s garden insect survey found.''","check":{"question":"What should an opening establish?","options":["Topic and purpose","Random detail only","No topic","Only a joke"],"correct_index":0,"explanation":"Topic and purpose is correct. Open: ''Today I''ll share what our class''s garden insect survey found.''"},"visual_before":[{"episode":{"title":"Presenting an Information Report","transcript":"pip: I need to learn presenting an information report. What should I check first?\njuno: Identify the relevant numbers or exact words, then follow a worked example.\npip: I''ll explain my strategy before deciding if the result is accurate.\njuno: Pause and try one step yourself, checking it against the evidence before moving on.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I need to learn presenting an information report. What should I check first?"},{"who":"juno","text":"Identify the relevant numbers or exact words, then follow a worked example."},{"who":"pip","text":"I''ll explain my strategy before deciding if the result is accurate."},{"who":"juno","text":"Pause and try one step yourself, checking it against the evidence before moving on.","pause_after":true}]}]}}]},{"icon":"📚","title":"Explain a labelled visual","explain":"Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations. The important concept here is: explain a labelled visual.","example":"**Worked example:** Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations.\n\n**Your practice:** Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations.","check":{"question":"Highest sample category?","options":["Bees 9","Butterflies 6","Beetles 2","All equal"],"correct_index":0,"explanation":"Bees 9 is correct. Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations."}},{"icon":"✏️","title":"Speak clearly using concise notes","explain":"Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences. The important concept here is: speak clearly using concise notes.","example":"**Worked example:** Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences.\n\n**Your practice:** Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences.","check":{"question":"What makes a chart interpretable?","options":["Labels, title and unit","Only colourful bars","No scale","Tiny words"],"correct_index":0,"explanation":"Labels, title and unit is correct. Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences."}},{"icon":"✅","title":"Respond to a question using evidence","explain":"If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results. The important concept here is: respond to a question using evidence.","example":"**Worked example:** If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results.\n\n**Your practice:** Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results.","check":{"question":"Why use cue cards?","options":["Recall key points","Avoid understanding","Hide the graph","Substitute for speaking"],"correct_index":0,"explanation":"Recall key points is correct. If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results."}}],"worked_example":"**Step 1: Introduce topic and purpose** Open: ''Today I''ll share what our class''s garden insect survey found.''\n\n**Step 2: Explain a labelled visual** Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations.\n\n**Step 3: Speak clearly using concise notes** Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences.\n\n**Step 4: Respond to a question using evidence** If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 170\"><rect width=\"570\" height=\"170\" rx=\"12\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"26\" font-family=\"Arial\" font-size=\"18\">Presenting an Information Report</text><rect x=\"8\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"15\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Introduce topic and</text><rect x=\"148\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"155\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Explain a labelled </text><rect x=\"288\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"295\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Speak clearly using</text><rect x=\"428\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"435\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Respond to a questi</text></svg>","alt":"Four concepts for Presenting an Information Report","caption":"Follow the explanations for each learning concept."}],"guided_practice":"Study the four models and practise their methods: Open: ''Today I''ll share what our class''s garden insect survey found.'' Explain a graph: bees 9, butterflies 6, beetles 2, with a vertical axis counting observations. Use a cue card for opening, observations, limitations and conclusion, speaking in clear connected sentences. If asked ''Are there always more bees?'', explain that one observation cannot establish every day''s results. Then explain how the facts or calculation check the result.","independent_task":"Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.","response_prompt":"Create and deliver a 60–90-second report on a fictional garden survey: bees 10, butterflies 7, beetles 3. Include a clear opening, labelled chart, two findings, one limitation and an ending. Answer one audience question and reflect on feedback. Signed, typed or recorded options are acceptable.","quiz":[{"type":"multiple_choice","question":"What should an opening establish?","options":["Topic and purpose","Random detail only","No topic","Only a joke"],"correct_index":0,"explanation":"Topic and purpose is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Highest sample category?","options":["Bees 9","Butterflies 6","Beetles 2","All equal"],"correct_index":0,"explanation":"Bees 9 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"What makes a chart interpretable?","options":["Labels, title and unit","Only colourful bars","No scale","Tiny words"],"correct_index":0,"explanation":"Labels, title and unit is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Why use cue cards?","options":["Recall key points","Avoid understanding","Hide the graph","Substitute for speaking"],"correct_index":0,"explanation":"Recall key points is correct; compare with the teaching example."},{"type":"multiple_choice","question":"Which inference is supported?","options":["One survey doesn''t prove every day","Every day is identical","All gardens match","Only bees visit flowers"],"correct_index":0,"explanation":"One survey doesn''t prove every day is correct; compare with the teaching example."},{"type":"multiple_choice","question":"What is a useful conclusion?","options":["Summarise supported findings","Invent global statistics","Ignore evidence","Add unrelated news"],"correct_index":0,"explanation":"Summarise supported findings is correct; compare with the teaching example."},{"type":"multiple_choice","question":"How answer an unknown question?","options":["Explain the evidence''s limits","Invent a fact","Blame listener","Repeat louder"],"correct_index":0,"explanation":"Explain the evidence''s limits is correct; compare with the teaching example."},{"type":"multiple_choice","question":"What is a constructive rehearsal change?","options":["Clarify an axis label","Remove title","Speak as fast as possible","Add unrelated facts"],"correct_index":0,"explanation":"Clarify an axis label is correct; compare with the teaching example."},{"type":"short_answer","question":"Complete the independent challenge and show the method.","sample_answer":"The chart''s highest category is bees (10), lowest is beetles (3), difference seven. An appropriate closing says the chart describes one observation, not all gardens.","marking_guide":"Check the full task against correct information and working.","explanation":"Specific evidence is essential."},{"type":"short_answer","question":"Explain a mistake, correction or important limitation.","sample_answer":"I clarified the chart''s ''number observed'' axis and paused before explaining the limitations. To ''Does this happen every day?'' I answer that one survey cannot establish that.","marking_guide":"Require a correct reason and topic-specific example.","explanation":"Use evidence to explain the change."}],"parent_notes":"Parent: Check the independent attempt before showing models.\n\nWritten model 1: The chart''s highest category is bees (10), lowest is beetles (3), difference seven. An appropriate closing says the chart describes one observation, not all gardens.\n\nWritten model 2: I clarified the chart''s ''number observed'' axis and paused before explaining the limitations. To ''Does this happen every day?'' I answer that one survey cannot establish that.\n\nRetain the student''s own evidence; NESA alignment is still unverified.","evidence_instructions":"Keep guided work, independent answers and written assessments.","offline_alternative":"Complete the tasks on paper and keep written or photographed evidence.","extension":"Design a new presenting an information report task and explain the answer.","stage_hints":{"accept":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach0":["Review Introduce topic and purpose.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach1":["Review Explain a labelled visual.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach2":["Review Speak clearly using concise notes.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach3":["Review Respond to a question using evidence.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"learn":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"guided":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"write":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"quiz":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"submit":["Review Presenting an Information Report.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."]}}') WHERE seed_key='s2-eng-y3-w10-l4';
UPDATE lessons SET title='Multiplication Facts: Threes and Fours',data=json_patch(data,'{"seed_key":"s2-mat-y3-w10-l1","title":"Multiplication Facts: Threes and Fours","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":10,"lesson_number":1,"duration_minutes":60,"child_mission":"Investigate multiplication facts: threes and fours with worked teaching and a new independent challenge.","learning_intention":"We are learning to understand and apply multiplication facts: threes and fours clearly.","success_criteria":["Explain the key idea.","Use a worked model.","Complete guided practice.","Solve an independent task.","Explain one check or correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Concept review","cards":[{"front":"Model equal groups of three","back":"Six groups of three are 3+3+3+3+3+3=18, so 6×3=18."},{"front":"Model equal groups of four","back":"Five groups of four are 4+4+4+4+4=20, so 5×4=20."},{"front":"Use arrays and commutativity","back":"A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots."},{"front":"Solve mixed-group problems","back":"Six three-chair tables and five four-chair tables hold 18+20=38 chairs."}]}],"printable_resource":{"title":"Multiplication Facts: Threes and Fours","instructions":"Read, model, practise, then independently respond.","passage":"Six groups of three are 3+3+3+3+3+3=18, so 6×3=18.","prompts":["Explain the topic.","Show one model.","Try a task.","Check the answer."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Model equal groups of three","explain":"Six groups of three are 3+3+3+3+3+3=18, so 6×3=18. The important concept here is: model equal groups of three.","example":"**Worked example:** Six groups of three are 3+3+3+3+3+3=18, so 6×3=18.\n\n**Your practice:** A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Six groups of three are 3+3+3+3+3+3=18, so 6×3=18.","check":{"question":"6×3?","options":["15","18","21","24"],"correct_index":1,"explanation":"18 is correct. Six groups of three are 3+3+3+3+3+3=18, so 6×3=18."},"visual_before":[{"episode":{"title":"Multiplication Facts: Threes and Fours","transcript":"pip: I need to learn multiplication facts: threes and fours. What should I check first?\njuno: Identify the relevant numbers or exact words, then follow a worked example.\npip: I''ll explain my strategy before deciding if the result is accurate.\njuno: Pause and try one step yourself, checking it against the evidence before moving on.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I need to learn multiplication facts: threes and fours. What should I check first?"},{"who":"juno","text":"Identify the relevant numbers or exact words, then follow a worked example."},{"who":"pip","text":"I''ll explain my strategy before deciding if the result is accurate."},{"who":"juno","text":"Pause and try one step yourself, checking it against the evidence before moving on.","pause_after":true}]}]}}]},{"icon":"📚","title":"Model equal groups of four","explain":"Five groups of four are 4+4+4+4+4=20, so 5×4=20. The important concept here is: model equal groups of four.","example":"**Worked example:** Five groups of four are 4+4+4+4+4=20, so 5×4=20.\n\n**Your practice:** A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Five groups of four are 4+4+4+4+4=20, so 5×4=20.","check":{"question":"5×4?","options":["16","18","20","24"],"correct_index":2,"explanation":"20 is correct. Five groups of four are 4+4+4+4+4=20, so 5×4=20."}},{"icon":"✏️","title":"Use arrays and commutativity","explain":"A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots. The important concept here is: use arrays and commutativity.","example":"**Worked example:** A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots.\n\n**Your practice:** A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots.","check":{"question":"7×3?","options":["18","21","24","27"],"correct_index":1,"explanation":"21 is correct. A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots."}},{"icon":"✅","title":"Solve mixed-group problems","explain":"Six three-chair tables and five four-chair tables hold 18+20=38 chairs. The important concept here is: solve mixed-group problems.","example":"**Worked example:** Six three-chair tables and five four-chair tables hold 18+20=38 chairs.\n\n**Your practice:** A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.\n\n**Check:** Compare each claim or calculation with the worked method.","notice":"Six three-chair tables and five four-chair tables hold 18+20=38 chairs.","check":{"question":"8×4?","options":["28","32","36","40"],"correct_index":1,"explanation":"32 is correct. Six three-chair tables and five four-chair tables hold 18+20=38 chairs."}}],"worked_example":"**Step 1: Model equal groups of three** Six groups of three are 3+3+3+3+3+3=18, so 6×3=18.\n\n**Step 2: Model equal groups of four** Five groups of four are 4+4+4+4+4=20, so 5×4=20.\n\n**Step 3: Use arrays and commutativity** A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots.\n\n**Step 4: Solve mixed-group problems** Six three-chair tables and five four-chair tables hold 18+20=38 chairs.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 170\"><rect width=\"570\" height=\"170\" rx=\"12\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"26\" font-family=\"Arial\" font-size=\"18\">Multiplication Facts: Threes and Fours</text><rect x=\"8\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"15\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Model equal groups </text><rect x=\"148\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"155\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Model equal groups </text><rect x=\"288\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e1efe4\"/><text x=\"295\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Use arrays and comm</text><rect x=\"428\" y=\"58\" width=\"130\" height=\"94\" rx=\"8\" fill=\"#e7eafb\"/><text x=\"435\" y=\"106\" font-family=\"Arial\" font-size=\"11\">Solve mixed-group p</text></svg>","alt":"Four concepts for Multiplication Facts: Threes and Fours","caption":"Follow the explanations for each learning concept."}],"guided_practice":"Study the four models and practise their methods: Six groups of three are 3+3+3+3+3+3=18, so 6×3=18. Five groups of four are 4+4+4+4+4=20, so 5×4=20. A three-by-seven array has 21 dots. A rotated seven-by-three array still has 21 dots. Six three-chair tables and five four-chair tables hold 18+20=38 chairs. Then explain how the facts or calculation check the result.","independent_task":"A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.","response_prompt":"A community hall has eight tables with three chairs each and seven tables with four chairs each. Find both subtotals and their combined total, draw an array, explain a mental strategy for 7×4 and why 15×3 is wrong.","quiz":[{"type":"multiple_choice","question":"6×3?","options":["15","18","21","24"],"correct_index":1,"explanation":"18 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"5×4?","options":["16","18","20","24"],"correct_index":2,"explanation":"20 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"7×3?","options":["18","21","24","27"],"correct_index":1,"explanation":"21 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"8×4?","options":["28","32","36","40"],"correct_index":1,"explanation":"32 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"3×7?","options":["18","21","24","28"],"correct_index":1,"explanation":"21 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"7×4?","options":["24","28","32","36"],"correct_index":1,"explanation":"28 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"8×3?","options":["21","24","27","30"],"correct_index":1,"explanation":"24 is correct; compare with the teaching example."},{"type":"multiple_choice","question":"8×3+7×4?","options":["48","52","56","60"],"correct_index":1,"explanation":"52 is correct; compare with the teaching example."},{"type":"short_answer","question":"Complete the independent challenge and show the method.","sample_answer":"8×3=24 chairs; 7×4=28 chairs; total 52 chairs. An eight-row array of three shows 24.","marking_guide":"Check the full task against correct information and working.","explanation":"Specific evidence is essential."},{"type":"short_answer","question":"Explain a mistake, correction or important limitation.","sample_answer":"7×4=28 by doubling seven to 14 and doubling again, or by counting seven groups of four. 15×3=45 is wrong because seven tables have four chairs.","marking_guide":"Require a correct reason and topic-specific example.","explanation":"Use evidence to explain the change."}],"parent_notes":"Parent: Check the independent attempt before showing models.\n\nWritten model 1: 8×3=24 chairs; 7×4=28 chairs; total 52 chairs. An eight-row array of three shows 24.\n\nWritten model 2: 7×4=28 by doubling seven to 14 and doubling again, or by counting seven groups of four. 15×3=45 is wrong because seven tables have four chairs.\n\nRetain the student''s own evidence; NESA alignment is still unverified.","evidence_instructions":"Keep guided work, independent answers and written assessments.","offline_alternative":"Complete the tasks on paper and keep written or photographed evidence.","extension":"Design a new multiplication facts: threes and fours task and explain the answer.","stage_hints":{"accept":["Review Multiplication Facts: Threes and Fours.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach0":["Review Model equal groups of three.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach1":["Review Model equal groups of four.","Find one exact number or text feature relevant to the task.","Explain how you can test whether the answer is accurate."],"teach2":["Review Use arrays and commutativi